// swift-tools-version: 6.0

import PackageDescription

// Idenzy for iOS and macOS (ADR-0022). `IdenzyCore` and `IdenzyCoreFFI` are generated by
// `scripts/build-apple.sh` from the Rust core; `Idenzy` is the hand-written layer an app imports.
let package = Package(
    name: "Idenzy",
    platforms: [.iOS(.v15), .macOS(.v12)],
    products: [
        .library(name: "Idenzy", targets: ["Idenzy"]),
        // For framework plugins (Flutter, React Native, Lynx, NativeScript), not for apps.
        .library(name: "IdenzyBridge", targets: ["IdenzyBridge"]),
    ],
    targets: [
        .binaryTarget(name: "IdenzyCoreFFI", path: "IdenzyCoreFFI.xcframework"),
        .target(
            name: "IdenzyCore",
            dependencies: ["IdenzyCoreFFI"],
            // Generated code, written for Swift 5 and annotated for 6; not ours to make strict.
            swiftSettings: [.swiftLanguageMode(.v5)]
        ),
        .target(name: "Idenzy", dependencies: ["IdenzyCore"]),
        .target(name: "IdenzyBridge", dependencies: ["Idenzy"]),
        .testTarget(name: "IdenzyTests", dependencies: ["Idenzy", "IdenzyBridge"]),
    ]
)
